// npm install @openpanel/web
import { OpenPanel } from '@openpanel/web';

export const op = new OpenPanel({
  clientId: 'YOUR_CLIENT_ID',
  apiUrl: 'https://api.privytics.com',
  trackScreenViews: true,
  trackOutgoingLinks: true,
});

// after your login or session-restore call resolves
op.identify({
  profileId: user.id,
  email: user.email,
  firstName: user.firstName,
  lastName: user.lastName,
  properties: {
    plan: user.plan,
    workspace_id: user.workspaceId,
    signup_week: user.signupWeek,
  },
});

// on logout
op.clear();

// 1. account created
op.track('signup_completed', { plan: 'free', source: 'pricing_page' });

// 2. first real setup step
op.track('workspace_created', { workspace_id: workspace.id });

// 3. the collaboration moment
op.track('teammate_invited', { invited_count: 3 });

// 4. the moment the product does its job
op.track('integration_connected', { provider: 'github' });
op.track('first_report_created', { report_type: 'funnel' });

// 5. the commercial steps
op.track('trial_started', { plan: 'pro' });
op.track('plan_upgraded', { from_plan: 'free', to_plan: 'pro' });
